        number = request["number"]
        if request["merged_at"] is not None:
            report["merged"].append(number)
        elif request["state"] == "open":
            report["open"].append(number)
        elif request["state"] == "closed":
            report["closed_unmerged"].append(number)

        if request["state"] == "open" and request["draft"] is True:
            report["open_drafts"].append(number)

    for key in ("merged", "open", "closed_unmerged", "open_drafts"):
        report[key].sort()

    with open("report.json", "w", encoding="utf-8") as handle:
        json.dump(report, handle)

    return report

